package com.autocare.platform.order;
import com.autocare.platform.ai.DeepSeekClient;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Actual MySQL/trust chain, explicitly synthetic vectors and AI completion. */
class JdbcKnowledgeVectorRetrievalTest extends JdbcLicensedKnowledgeTest {
 KnowledgeEmbeddingRuntime runtime;EmbeddingProfile profile=EmbeddingFoundationTest.profile();AtomicInteger calls=new AtomicInteger();
 EmbeddingProvider provider=(p,texts)->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());return new EmbeddingProvider.Output(p.fingerprint(),texts.stream().map(t->t.contains("制动")||t.contains("刹车")?new double[]{1,0,0}:new double[]{0,1,0}).toList());};
 @AfterEach void closeRuntime(){if(runtime!=null)runtime.close();}
 ObjectNode allowed(String body){return config().put("body",body).put("embedding_allowed",true).put("embedding_policy_version",KnowledgeInput.EMBEDDING_POLICY);}
 long published(ObjectNode value){long id=createKnowledge(value);publishKnowledge(id);return id;}
 long indexed(ObjectNode body){long id=published(body);try(var index=new KnowledgeVectorIndex(db,knowledge,profile,provider,true)){index.enqueue(id);assertTrue(index.workOne());}return id;}
 void start(){runtime=new KnowledgeEmbeddingRuntime(db,knowledge,profile,provider,true,false,true);knowledge.embeddingRuntime(runtime);}
 JsonNode search(String q){return json.valueToTree(knowledge.search(owner,1,q,null));}
 ObjectNode question(String q){return json.createObjectNode().put("vehicle_id",1).put("question",q);}
 DeepSeekClient.Completion reply(){return new DeepSeekClient.Completion("合成回答，不代表诊断。","synthetic-ai",1,1);}
 @Test void publicVectorReturnsTheActualLaterUnicodeChunkAndIndependentDetail(){
  String body="背景资料😀 ".repeat(90)+"制动检查说明：请到店核查，不表示诊断。";long id=indexed(allowed(body));start();var found=search("刹车");assertEquals("VECTOR",found.path("method").asText());assertFalse(found.has("fallback_reason"));assertTrue(found.path("next_cursor").isNull());var item=found.path("items").get(0);assertTrue(item.path("chunk").asInt()>0);int begin=item.path("start_offset").asInt(),end=item.path("end_offset").asInt();assertEquals(body.substring(begin,end),item.path("excerpt").asText());assertTrue(item.path("excerpt").asText().contains("制动"));assertFalse(item.toString().contains("profile_hash"));assertFalse(item.toString().contains("license_reference"));
  var detail=json.valueToTree(knowledge.detail(owner,1,item.path("reference").asText(),item.path("chunk").asInt()));assertEquals(item.path("excerpt"),detail.path("document").path("body"));assertEquals(begin,detail.path("document").path("start_offset").asInt());
 }
 @Test void anySearchableSourceWithoutEmbeddingConsentUsesExplicitKeyword(){indexed(allowed("冷却液合成说明"));published(config());int before=calls.get();start();var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertEquals("INDEX_NOT_READY",out.path("fallback_reason").asText());assertEquals(before,calls.get());}
 @Test void missingCurrentIndexNeverClaimsPartialVectorCoverage(){indexed(allowed("冷却液合成说明"));published(allowed("新的冷却液说明"));int before=calls.get();start();assertEquals("INDEX_NOT_READY",search("冷却液").path("fallback_reason").asText());assertEquals(before,calls.get());}
 @Test void unavailableProviderFallsBackToCurrentKeywordSources(){indexed(allowed("冷却液合成说明"));provider=(p,t)->{throw new EmbeddingProvider.Failed("UNAVAILABLE");};start();var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertEquals("VECTOR_UNAVAILABLE",out.path("fallback_reason").asText());assertEquals(1,out.path("items").size());}
 @Test void corruptedOrMissingChunksCannotBeReturnedAsVector(){indexed(allowed("冷却液说明"));jdbc.update("DELETE FROM knowledge_embedding_chunk");start();var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertEquals("VECTOR_UNAVAILABLE",out.path("fallback_reason").asText());}
 @Test void wrongOwnerScopeFailsBeforeModelInsteadOfDowngradingAuthorization(){indexed(allowed("冷却液说明"));int before=calls.get();start();assertEquals(404,code(()->knowledge.search(owner,2,"冷却液",null)));assertEquals(before,calls.get());}
 @Test void revokedOwnerDuringQueryIsNotConvertedToAKeywordSuccess(){indexed(allowed("冷却液说明"));var actual=provider;provider=(p,t)->{jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",owner.session());return actual.embed(p,t);};start();assertEquals(401,code(()->knowledge.search(owner,1,"冷却液",null)));}
 @Test void modelChangeDuringQueryCannotExposeThePreviousModel(){indexed(allowed("冷却液说明"));jdbc.update("INSERT INTO model(id,series_id,year,config_name,status) VALUES(2,1,'2027','synthetic other model',1)");var actual=provider;provider=(p,t)->{jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=1");return actual.embed(p,t);};start();var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertEquals(0,out.path("items").size());}
 @Test void newlyPublishedUnindexedSourceDuringQueryForcesFreshKeyword(){indexed(allowed("冷却液说明"));var actual=provider;provider=(p,t)->{published(allowed("新增冷却液资料"));return actual.embed(p,t);};start();var out=search("冷却液");assertEquals("INDEX_NOT_READY",out.path("fallback_reason").asText());assertEquals(2,out.path("items").size());}
 @Test void stoppedSourceDuringQueryIsHiddenEvenBeforeCleanup(){long id=indexed(allowed("冷却液说明"));var actual=provider;provider=(p,t)->{knowledge.status(manager,id,key(),state(2,"STOPPED"));return actual.embed(p,t);};start();var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertEquals(0,out.path("items").size());assertTrue(count("knowledge_embedding_chunk")>0);}
 @Test void aiVectorUsesOnlyCurrentAiLicensedExactExcerpts(){indexed(allowed("制动合成说明").put("ai_allowed",false));indexed(allowed("冷却液合成说明"));start();when(ai.complete(anyString(),anyList(),anyInt())).thenAnswer(i->{String input=((List<DeepSeekClient.Message>)i.getArgument(1)).get(0).content();assertFalse(input.contains("license_reference"));assertFalse(input.contains("制动合成说明"));assertTrue(input.contains("start_offset"));return reply();});var out=json.valueToTree(knowledge.answer(owner,question("刹车")));assertEquals("VECTOR",out.path("method").asText());assertEquals(1,out.path("provided_sources").size());assertTrue(out.path("provided_sources").get(0).path("ai_allowed").asBoolean());}
 @Test void aiReferenceRevocationAfterUpstreamWithholdsTheAnswer(){long id=indexed(allowed("冷却液合成说明"));start();when(ai.complete(anyString(),anyList(),anyInt())).thenAnswer(i->{knowledge.status(manager,id,key(),state(2,"STOPPED"));return reply();});assertEquals(404,code(()->knowledge.answer(owner,question("冷却液"))));}
 @Test void closingVectorRuntimeDuringAiNeverRelabelsAnOldAnswerAsKeyword(){indexed(allowed("冷却液说明"));start();when(ai.complete(anyString(),anyList(),anyInt())).thenAnswer(i->{runtime.close();return reply();});assertEquals(503,code(()->knowledge.answer(owner,question("冷却液"))));}
 @Test void longOrMultilineAiQuestionUsesFullKeywordQuestionWithoutTruncation(){indexed(allowed("冷却液说明"));int before=calls.get();start();when(ai.complete(anyString(),anyList(),anyInt())).thenReturn(reply());for(String text:List.of("冷却液".repeat(30),"冷却液\n检查")){var out=json.valueToTree(knowledge.answer(owner,question(text)));assertEquals("KEYWORD",out.path("method").asText());assertEquals("QUERY_LIMIT",out.path("fallback_reason").asText());}assertEquals(before,calls.get());}
 @Test void cursorPaginationStaysKeywordAndDoesNotUseVectorPositions(){long id=indexed(allowed("冷却液说明"));int before=calls.get();start();var out=json.valueToTree(knowledge.search(owner,1,"冷却液",id+1));assertEquals("CURSOR_PAGING",out.path("fallback_reason").asText());assertEquals("KEYWORD",out.path("method").asText());assertFalse(out.path("items").get(0).has("chunk"));assertEquals(before,calls.get());}
 @Test void detailPreservesLegacyShapeAndRequiresEmbeddingConsentForPositionedReads(){long id=published(config());String ref=jdbc.queryForObject("SELECT public_id FROM knowledge_document WHERE id=?",String.class,id);assertFalse(json.valueToTree(knowledge.detail(owner,1,ref)).path("document").has("chunk"));assertEquals(404,code(()->knowledge.detail(owner,1,ref,0)));assertEquals(404,code(()->knowledge.detail(owner,2,ref)));}
 @Test void vectorReadDoesNotWriteTasksKnowledgeEventsAuditOrReceipts(){indexed(allowed("冷却液说明"));start();int jobs=count("knowledge_embedding_job"),chunks=count("knowledge_embedding_chunk"),audits=count("audit_log"),events=count("knowledge_document_event");String before=jdbc.queryForObject("SELECT profile_json FROM knowledge_embedding_job",String.class);assertEquals("VECTOR",search("冷却液").path("method").asText());assertEquals(jobs,count("knowledge_embedding_job"));assertEquals(chunks,count("knowledge_embedding_chunk"));assertEquals(audits,count("audit_log"));assertEquals(events,count("knowledge_document_event"));assertEquals(before,jdbc.queryForObject("SELECT profile_json FROM knowledge_embedding_job",String.class));}
 @Test void defaultRuntimeKeepsLegacyKeywordWithoutFallbackMetadata(){indexed(allowed("冷却液说明"));int before=calls.get();runtime=new KnowledgeEmbeddingRuntime(db,knowledge,profile,provider,true,false);knowledge.embeddingRuntime(runtime);var out=search("冷却液");assertEquals("KEYWORD",out.path("method").asText());assertFalse(out.has("fallback_reason"));assertFalse(out.path("items").get(0).has("chunk"));assertEquals(before,calls.get());}
 @Test void vectorTopFiveIsUniqueAndHasNoKeywordCursor(){for(int i=0;i<6;i++)indexed(allowed("制动合成说明"));start();var out=search("刹车");assertEquals("VECTOR",out.path("method").asText());assertEquals(5,out.path("items").size());assertTrue(out.path("next_cursor").isNull());}
 @Test void wrongProfileCannotReuseSuccessfulOldVectors(){indexed(allowed("冷却液说明"));int before=calls.get();profile=new EmbeddingProfile(profile.model(),"b".repeat(40),3,profile.queryPrefix());start();assertEquals("INDEX_NOT_READY",search("冷却液").path("fallback_reason").asText());assertEquals(before,calls.get());}
}
